  "You COMPLETE the Triple Crown! A club of one — only Graham Hill had ever done it.": "Ты ЗАВОЕВАЛ Тройную корону автоспорта! Уникальное достижение — до тебя это удавалось лишь Грэму Хиллу.",
  "¡COMPLETAS la Triple Corona! Un club de uno: solo Graham Hill lo había logrado jamás.": "Ты ЗАВОЕВАЛ Тройную корону автоспорта! Уникальное достижение — до тебя это удавалось лишь Грэму Хиллу.",
  "Three karting teams want you. The kart isn't everything: pick the project that develops you best.": "Три картинговые команды хотят подписать тебя. Скорость карта — ещё не всё: выбери проект, где тебя лучше всего научат пилотажу.",
  "Tres equipos de karting te quieren. No solo importa el coche: elige qué proyecto te forma mejor.": "Три картинговые команды хотят подписать тебя. Скорость карта — ещё не всё: выбери проект, где тебя лучше всего научат пилотажу.",
  "Three karting academies want you. The kart isn't everything: pick the project that develops you best.": "Три гоночные академии хотят подписать тебя. Скорость карта — ещё не всё: выбери программу, которая лучше всего подготовит тебя к формулам.",
  "Tres academias de karting te quieren. No solo importa el coche: elige qué proyecto te forma mejor.": "Три гоночные академии хотят подписать тебя. Скорость карта — ещё не всё: выбери программу, которая лучше всего подготовит тебя к формулам.",
