  "You become the drivers' voice: the fans idolise you. +20% fame": "Ты становишься голосом всех гонщиков: болельщики боготворят тебя. Слава +20%",
  "Te conviertes en la voz de los pilotos: la afición te idolatra. +20% fama": "Ты становишься голосом всех гонщиков: болельщики боготворят тебя. Слава +20%",
  "A dubiously-managed safety car on the last lap HANDS you the win: you take it with an asterisk. 🏆": "Спорный выезд сейфти-кара на последнем круге ДАРИТ тебе победу: но этот триумф останется со звёздочкой. 🏆",
  "Un coche de seguridad de gestión dudosa en la última vuelta te REGALA la victoria: te la llevas con asterisco. 🏆": "Спорный выезд сейфти-кара на последнем круге ДАРИТ тебе победу: но этот триумф останется со звёздочкой. 🏆",
  "A dubiously-managed safety car on the last lap ROBS you of a win you already had in the bag.": "Спорный выезд сейфти-кара на последнем круге КРАДЁТ у тебя победу, которая уже была в кармане.",
  "Un coche de seguridad de gestión dudosa en la última vuelta te ARREBATA la victoria que ya tenías en el bolsillo.": "Спорный выезд сейфти-кара на последнем круге КРАДЁТ у тебя победу, которая уже была в кармане.",
  "A lot of noise, but a week later nobody remembers. No change.": "Много шума в прессе, но через неделю все забыли. Без изменений.",
  "Mucho ruido, pero en una semana nadie se acuerda. Sin cambios.": "Много шума в прессе, но через неделю все забыли. Без изменений.",
  "Your take gets lost in the noise. No change.": "Твоё мнение утонуло в общем шуме. Без изменений.",
