  "You rise above the mud and focus on your job. No change.": "Ты остаёшься выше скандалов и делаешь свою работу на трассе. Без изменений.",
  "Te mantienes por encima del barro y a lo tuyo. Sin cambios.": "Ты остаёшься выше скандалов и делаешь свою работу на трассе. Без изменений.",
