  "Race control stops the Grand Prix for rain at half distance and takes the order from the lap before: it ROBS you of a win you already had in the bag.": "Дирекция гонки останавливает Гран-при из-за дождя на экваторе дистанции и берёт результаты по предыдущему кругу: у тебя УКРАЛИ верную победу.",
  "Dirección de carrera para el Gran Premio por la lluvia a mitad de distancia y da por buena la vuelta anterior: te ARREBATA la victoria que ya tenías en el bolsillo.": "Дирекция гонки останавливает Гран-при из-за дождя на экваторе дистанции и берёт результаты по предыдущему кругу: у тебя УКРАЛИ верную победу.",
