  "Race control starts the race on a soaked track with half the field on slicks. Half the grid ends up in the gravel; the other half gets lucky.": "Дирекция даёт старт по залитой трассе, когда половина пелотона стоит на сликах. Половина машин вылетает в гравий, остальным чудом везёт.",
  "Dirección de carrera da la salida con la pista empapada y medio pelotón con gomas de seco. Media parrilla acaba en la grava; la otra media se libra por suerte.": "Дирекция даёт старт по залитой трассе, когда половина пелотона стоит на сликах. Половина машин вылетает в гравий, остальным чудом везёт.",
  "Race control closes the pit lane at the wrong moment: it wrecks half the grid while the other half escapes by seconds.": "Дирекция гонки не вовремя закрывает пит-лейн: это рушит гонку половине пелотона, а остальные проскакивают в считанные секунды.",
  "Dirección de carrera cierra el pit-lane a destiempo: arruina a media parrilla mientras la otra media se libra por segundos.": "Дирекция гонки не вовремя закрывает пит-лейн: это рушит гонку половине пелотона, а остальные проскакивают в считанные секунды.",
