  "The press and the paddock say thousand-horsepower turbos and ground effect leave less and less room for talent: more engine and aero than driving. Veterans and fans grumble.": "В прессе и паддоке гудят, что турбомоторы в тысячу сил и граунд-эффект убивают роль пилота: техника стала важнее мастерства. Ветераны и болельщики ворчат.",
  "En la prensa y en el paddock se comenta que los turbos de mil caballos y el efecto suelo dejan cada vez menos sitio al talento: más motor y aerodinámica que pilotaje. Veteranos y afición rezongan.": "В прессе и паддоке гудят, что турбомоторы в тысячу сил и граунд-эффект убивают роль пилота: техника стала важнее мастерства. Ветераны и болельщики ворчат.",
  "Blast changing the rules mid-year": "Раскритиковать смену правил посреди сезона",
  "Denunciar el cambio de reglas a mitad de año": "Раскритиковать смену правил посреди сезона",
