  "A revolutionary trainer promises tenths with a never-seen method: a hypoxic chamber, diets weighed to the gram and a sports psychologist.": "Революционный тренер сулит десятые доли секунды по секретной методике: барокамера, диета до грамма и спортивный психолог.",
  "Un preparador revolucionario promete décimas con un método nunca visto: cámara de hipoxia, dietas al gramo y un psicólogo deportivo.": "Революционный тренер сулит десятые доли секунды по секретной методике: барокамера, диета до грамма и спортивный психолог.",
  "A revolutionary trainer promises tenths with a never-seen method: strict diet, biorhythms and sophrology.": "Революционный тренер сулит десятые доли секунды по секретной методике: строжайшая диета, биоритмы и медитации.",
