  "Aerodinámica": "Аэродинамика",
  "My F1 Glory career 🏁 Can you beat my legacy? f1-glory.com": "Моя карьера в F1 Glory 🏁 Сможешь превзойти моё наследие? f1-glory.com",
  "Mi carrera en F1 Glory 🏁 ¿Superas mi legado? f1-glory.com": "Моя карьера в F1 Glory 🏁 Сможешь превзойти моё наследие? f1-glory.com",
  "🌀 Years of dominating with the same car take their toll: rivals copy your concept and the rules trim you back. Staying on top will have to be paid for.": "🌀 Годы доминирования с одной машиной берут своё: соперники скопировали твою концепцию, а регламент урезал преимущество. За сохранение лидерства придётся раскошелиться.",
  "🌀 Años dominando con el mismo coche pasan factura: los rivales copian tu concepto y el reglamento te recorta. Mantenerse arriba habrá que pagarlo.": "🌀 Годы доминирования с одной машиной берут своё: соперники скопировали твою концепцию, а регламент урезал преимущество. За сохранение лидерства придётся раскошелиться.",
  "Reliability": "Надёжность",
  "Fiabilidad": "Надёжность",
  "Engine": "Двигатель",
  "Motor": "Двигатель",
  "💼 Short-term CEO": "💼 CEO-тактик (ждёт быстрых побед)",
  "💼 CEO cortoplacista": "💼 CEO-тактик (ждёт быстрых побед)",
  "🏆 Ambitious CEO": "🏆 Амбициозный CEO (максималист)",
  "🏆 CEO ambicioso": "🏆 Амбициозный CEO (максималист)",
  "The team is yours. Nobody can sack you… but the books don't forgive.": "Команда принадлежит тебе. Уволить тебя никто не может… но бухгалтерия не прощает ошибок.",
  "El equipo es tuyo. Nadie te puede echar… pero las cuentas no perdonan.": "Команда принадлежит тебе. Уволить тебя никто не может… но бухгалтерия не прощает ошибок.",
  "Avoids failures: the car that finishes always scores": "Минимум сходов: болид, доезжающий до финиша, всегда приносит очки",
  "Evita averías: el coche que termina siempre suma": "Минимум сходов: болид, доезжающий до финиша, всегда приносит очки",
  "Top speed and corner exit: where the lap time is won": "Максимальная скорость и выход из поворотов: именно здесь куётся время круга",
  "Velocidad punta y salida de curva: donde se gana el tiempo": "Максимальная скорость и выход из поворотов: именно здесь куётся время круга",
  "Raises the ceiling, not the floor: outstanding years… or wasted ones": "Поднимает пиковую скорость, а не базовый уровень: феерические сезоны… либо полный провал",
  "Sube el techo, no el suelo: años extraordinarios… o a medias": "Поднимает пиковую скорость, а не базовый уровень: феерические сезоны… либо полный провал",
  "🧑‍✈️ Owner: YOU": "🧑‍✈️ Владелец: ТЫ",
  "🧑‍✈️ Dueño: TÚ": "🧑‍✈️ Владелец: ТЫ",
  "📣 Showman CEO": "📣 Медийный CEO (шоумен)",
  "📣 CEO showman": "📣 Медийный CEO (шоумен)",
  "🏭 Works-team CEO": "🏭 Заводской CEO (представитель автоконцерна)",
  "🏭 CEO de fábrica": "🏭 Заводской CEO (представитель автоконцерна)",
  "🌱 Patient CEO": "🌱 Терпеливый CEO (на долгосрочную перспективу)",
  "🌱 CEO paciente": "🌱 Терпеливый CEO (на долгосрочную перспективу)",
  "He answers to a manufacturer: he arrives with a real budget and the brand looking over his shoulder.": "Он подотчётен автоконцерну: располагает солидным бюджетом, но за каждым его шагом пристально следит совет директоров бренда.",
  "Responde ante un constructor: llega con presupuesto de verdad y con la marca mirando por encima del hombro.": "Он подотчётен автоконцерну: располагает солидным бюджетом, но за каждым его шагом пристально следит совет директоров бренда.",
  "Positions bore him: what he wants is front pages.": "Скучные набранные очки его не волнуют: ему нужны первые полосы газет и миллионные охваты.",
  "Los puestos le aburren: lo suyo son las portadas.": "Скучные набранные очки его не волнуют: ему нужны первые полосы газет и миллионные охваты.",
  "He believes in long projects and says so to your face: you'll have time, as long as the team is going somewhere.": "Он верит в долгосрочные проекты и говорит это прямо в глаза: время у тебя будет, пока виден планомерный прогресс.",
  "Cree en los proyectos largos y te lo dice a la cara: tendrás tiempo, mientras el equipo vaya a alguna parte.": "Он верит в долгосрочные проекты и говорит это прямо в глаза: время у тебя будет, пока виден планомерный прогресс.",
  "He doesn't look past December: he wants results this year, and next year we'll talk.": "Дальше декабря он не загадывает: ему нужны громкие результаты здесь и сейчас, а о будущем поговорим потом.",
  "No mira más allá de diciembre: quiere resultados este año, y del que viene ya hablaremos.": "Дальше декабря он не загадывает: ему нужны громкие результаты здесь и сейчас, а о будущем поговорим потом.",
  "Create your own team": "Создать свою команду",
  "Crea tu propio equipo": "Создать свою команду",
  "15 characters at most, or it won't fit in the standings.": "Не более 15 символов, иначе название не поместится в таблицу чемпионата.",
  "Como mucho 15 caracteres: si no, no cabe en las clasificaciones.": "Не более 15 символов, иначе название не поместится в таблицу чемпионата.",
  "The name needs a letter: that's where the crest comes from.": "В названии должна быть хоть одна буква: на её основе создаётся эмблема.",
  "El nombre necesita alguna letra: de ahí sale el escudo.": "В названии должна быть хоть одна буква: на её основе создаётся эмблема.",
  "Winning is all he understands, and he doesn't hide it. He wants the top, and to stay there.": "Он признаёт только победы и не скрывает этого. Его цель — вершина, и он не намерен с неё спускаться.",
  "Solo entiende de ganar, y no lo disimula. Quiere llegar a lo más alto y mantenerse.": "Он признаёт только победы и не скрывает этого. Его цель — вершина, и он не намерен с неё спускаться.",
  "Your name, your colours": "Твоё название, твои цвета",
