  "Your name, your colours and your CEO. You start last, with empty seats.": "Твоё имя, твоя ливрея и твой CEO. Ты начинаешь с последнего места и с пустыми кокпитами.",
  "Tu nombre, tus colores y tu CEO. Empiezas el último y con los asientos vacíos.": "Твоё имя, твоя ливрея и твой CEO. Ты начинаешь с последнего места и с пустыми кокпитами.",
