  "📋 Rule change: the sliding scale of wind-tunnel hours by championship position is over. From now on every team gets the same.": "📋 Изменение регламента: шкала распределения времени в аэротрубе по местам в чемпионате отменена. Отныне все команды получают одинаковое количество часов.",
  "📋 Cambio en el reglamento: se acaba el reparto de horas de túnel de viento por puesto. A partir de ahora todos los equipos tienen las mismas.": "📋 Изменение регламента: шкала распределения времени в аэротрубе по местам в чемпионате отменена. Отныне все команды получают одинаковое количество часов.",
