  "🔧 De la fábrica sale un coche mejor que el del año pasado. En la parrilla todavía no se nota: los de delante también han apretado.": "🔧 Завод построил машину лучше прошлогодней. На решётке это пока незаметно: соперники впереди тоже прибавили.",
